// components/Clock.js
import React, { useState, useEffect } from 'react';

const Clock = () => {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const interval = setInterval(() => {
      setTime(new Date());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="global-footer-clock">
      <i className="fas fa-clock"></i>
      <div>
        <div id="clockTime">{time.toLocaleTimeString()}</div>
        <div id="clockDate">{time.toLocaleDateString()}</div>
      </div>
    </div>
  );
};

export default Clock;
